#include <cstdint>
#include <iostream>

#include "golden_vectors.h"  // generated by train_vae.py from hls4ml's bit-accurate model
#include "vae_axis.hpp"

namespace {

constexpr int kFeatureCount = 8;

void write_beat(hls::stream<vae_feature_beat_t>& input, std::int32_t feature, bool last,
                unsigned keep, unsigned strb) {
    vae_feature_beat_t beat;
    beat.data = static_cast<std::uint32_t>(feature) & 0x1ffffff;
    beat.last = last;
    beat.keep = keep;
    beat.strb = strb;
    input.write(beat);
}

void write_flow(hls::stream<vae_feature_beat_t>& input, int row, bool last = true,
                unsigned keep = 0xf, unsigned strb = 0xf) {
    for (int i = 0; i < kFeatureCount; ++i) {
        write_beat(input, kGoldenFeatures[row][i], last && i == kFeatureCount - 1, keep, strb);
    }
}

bool check_score(hls::stream<vae_score_beat_t>& output, int row) {
    if (output.empty()) {
        std::cerr << "Missing score beat for row " << row << '\n';
        return false;
    }
    const vae_score_beat_t beat = output.read();
    const std::uint64_t got = beat.data.to_uint64();
    if (got != kGoldenScores[row] || beat.keep != 0xff || beat.strb != 0xff || !beat.last) {
        std::cerr << "Row " << row << ": expected score code " << kGoldenScores[row] << ", got " << got
                  << " TKEEP=" << beat.keep << " TSTRB=" << beat.strb << " TLAST=" << beat.last << '\n';
        return false;
    }
    return true;
}

}  // namespace

int main() {
    hls::stream<vae_feature_beat_t> input;
    hls::stream<vae_score_beat_t> output;

    // 1. Every golden vector must match the hls4ml bit-accurate score exactly.
    int failures = 0;
    for (int r = 0; r < kGoldenCount; ++r) {
        write_flow(input, r);
        vae_axis(input, output);
        failures += !check_score(output, r);
    }
    if (failures) {
        std::cerr << failures << " golden mismatches\n";
        return 1;
    }

    // 2. Framing rules identical to deep_svdd_axis.
    write_flow(input, 0);
    write_beat(input, 1, true, 0xf, 0xf);  // early TLAST
    write_flow(input, 0, false);
    write_beat(input, 1, false, 0xf, 0xf);
    write_beat(input, 2, true, 0xf, 0xf);  // late TLAST
    write_flow(input, 0, true, 0x7, 0x7);  // bad TKEEP
    write_flow(input, 0, true, 0xf, 0x7);  // bad TSTRB
    write_flow(input, 1);
    write_flow(input, 0);

    vae_axis(input, output);
    if (!check_score(output, 0) || !output.empty()) return 1;
    for (int i = 0; i < 4; ++i) {
        vae_axis(input, output);
        if (!output.empty()) {
            std::cerr << "Unexpected score for malformed frame " << i + 1 << '\n';
            return 1;
        }
    }
    vae_axis(input, output);
    vae_axis(input, output);
    if (!check_score(output, 1) || !check_score(output, 0) || !input.empty() || !output.empty()) return 1;

    std::cout << "VAE AXI4-Stream tests passed (" << kGoldenCount << " golden vectors + framing)\n";
    return 0;
}
